// Read-only GitHub monitoring. No dispatch, engine downloads, or local execution.
import assert from 'node:assert/strict';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {existsSync, readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
const exec=promisify(execFile), run=37201401969;
const root='/mnt/storage/code/labwired-evidence/labwired-same-host-20261003.R0T0cC/discovery-census-r2-20261004';
const statePath=root+'/observation-resumed.json';
assert(!existsSync(statePath),'Inspect existing observer state rather than repeat');
const state={run,source:'1b044ea97d2a72c43f1b15a147d64a479620f0ee',
 diagnosticOnly:true,dispatch:false,enginePromotion:false,localEngineDownloads:false,
 priorObservation: {"path":"/mnt/storage/code/labwired-evidence/labwired-same-host-20261003.R0T0cC/discovery-census-r2-20261004/observation.json","error":"Command failed: gh run view -R CrispStrobe/labwired-core --job 111433671651 --log\nrun 37201401969 is still in progress; logs will be available when it is complete\n"}, startedAt:new Date().toISOString(),logs:[]};
async function persist(path,value){
 const next=JSON.stringify(value,null,2)+'\n';
 const prefix=existsSync(path)?'*** Update File: '+path+'\n@@\n'+
  readFileSync(path,'utf8').trimEnd().split('\n').map(l=>'-'+l).join('\n')+'\n':
  '*** Add File: '+path+'\n';
 const patch='*** Begin Patch\n'+prefix+next.trimEnd().split('\n').map(l=>'+'+l).join('\n')+'\n*** End Patch\n';
 const child=exec('apply_patch',[],{encoding:'utf8',timeout:30000,maxBuffer:1024*1024});
 child.child.stdin.end(patch);await child;
}
const gh=async args=>(await exec('gh',args,{encoding:'utf8',timeout:30000,
 maxBuffer:4*1024*1024})).stdout;
async function read(args){for(let i=0;;i++){try{return await gh(args);}catch(error){
 if(i===2)throw error;await new Promise(r=>setTimeout(r,2000));}}}
await persist(statePath,state);
const deadline=Date.now()+2*60*60*1000;
try{
 while(Date.now()<deadline){
  const snapshot=JSON.parse(await read(['run','view',String(run),'-R','CrispStrobe/labwired-core',
   '--json','headSha,status,conclusion,jobs,url']));
  assert.equal(snapshot.headSha,state.source);
  state.snapshot=snapshot;state.observedAt=new Date().toISOString();
  for(const job of snapshot.jobs){
   if(job.status!=='completed'||job.conclusion==='skipped'||state.logs.some(l=>l.job===job.databaseId))continue;
   const raw=await read(['api','repos/CrispStrobe/labwired-core/actions/jobs/'+job.databaseId+'/logs']);
   const bytes=Buffer.from(raw,'utf8');
   const record={job:job.databaseId,name:job.name,conclusion:job.conclusion,
    bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex'),
    encoding:'utf8',text:raw};
   const path=root+'/job-'+job.databaseId+'-log.utf8.json';
   assert(!existsSync(path),'Do not overwrite an original log');
   await persist(path,record);state.logs.push({job:job.databaseId,path,
    bytes:record.bytes,sha256:record.sha256});
  }
  await persist(statePath,state);
  console.log(JSON.stringify({run,status:snapshot.status,conclusion:snapshot.conclusion,
   jobs:snapshot.jobs.map(j=>({name:j.name,status:j.status,conclusion:j.conclusion}))}));
  if(snapshot.status==='completed'){
   state.completedAt=new Date().toISOString();await persist(statePath,state);break;
  }
  await new Promise(r=>setTimeout(r,45000));
 }
 if(!state.completedAt){state.monitoringDeadlineAt=new Date().toISOString();await persist(statePath,state);}
}catch(error){state.error=error.message;await persist(statePath,state);throw error;}
